import { closeSync, constants, fstatSync, openSync, readSync, readdirSync } from 'node:fs';
import path from 'node:path';
// The validator's lexer retains raw bytes and numeric lexemes and rejects duplicate keys.
// @ts-expect-error The validator is a JavaScript package without declarations.
import { readJsonl } from '../../../tools/validator/src/jsonl.js';
// @ts-expect-error The validator is a JavaScript package without declarations.
import { validateRecord } from '../../../tools/validator/src/index.js';
// @ts-expect-error The shared schemas are generated by a JavaScript package.
import { buildSchemas } from '../../../tools/validator/src/schema/build.js';

const referencePattern = new RegExp(buildSchemas().record.$defs.SessionRef.pattern);
export const isReference = (value: unknown): value is string => typeof value === 'string' && referencePattern.test(value);

export type RecordData = Record<string, any>;
export type Diagnostic = { code: string; line?: number; session?: string };
export type Session = {
  ref: string; header: RecordData; records: RecordData[]; raw: string[];
  original: Set<RecordData>; missing: string[]; diagnostics: Diagnostic[];
};
export type AnnotationFile = { records: RecordData[]; diagnostics: Diagnostic[] };

export function component(value: string): string {
  return value.replace(/[%:#\s\x00-\x1f\x7f-\x9f]/gu, c => encodeURIComponent(c) === c
    ? `%${c.charCodeAt(0).toString(16).toUpperCase().padStart(2, '0')}` : encodeURIComponent(c));
}
export function reference(h: RecordData): string {
  return [h.agent.name, ...(h.namespace === undefined ? [] : [component(h.namespace)]), component(h.sessionId)].join(':');
}
export function citation(s: Session, r: RecordData): string { return `${s.ref}#${component(r.id)}`; }

export function readSession(input: Uint8Array): Session {
  const parsed = readJsonl(input);
  const header = parsed.records.find((r: any) => r.line === 1)?.value;
  if (header?.type !== 'session' || header.formatVersion !== '0.1' || typeof header.agent?.name !== 'string'
      || typeof header.sessionId !== 'string' || !header.sessionId || validateRecord(header).length)
    throw new Error('A supported session header is required on line 1.');
  const records: RecordData[] = [];
  const diagnostics: Diagnostic[] = parsed.diagnostics.map((d: any) => ({ code: d.code, line: d.line }));
  for (const row of parsed.records.slice(1)) {
    const errors = validateRecord(row.value, 'record', row.numbers);
    if (errors.length) diagnostics.push({ code: 'invalid-record-shape', line: row.line });
    else records.push(row.value);
  }
  const ids = new Set([header.id]);
  let unsafe = diagnostics.some(d => d.code !== 'incomplete-line');
  for (const r of records) {
    if (typeof r.id !== 'string' || ids.has(r.id) || r.type === 'session') {
      diagnostics.push({ code: 'invalid-record-identity' }); unsafe = true;
    }
    ids.add(r.id);
  }
  const boundary = header.parent?.copiedThrough;
  const boundaryIndex = boundary === undefined ? -1 : records.findIndex(r => r.id === boundary);
  if (boundary !== undefined && boundaryIndex < 0) { diagnostics.push({ code: 'unresolved-copy-boundary' }); unsafe = true; }
  const original = new Set(unsafe ? [] : records.filter((r, i) => i > boundaryIndex && !r.copiedFrom));
  const missing = [...new Set<string>([header, ...records.filter(r => r.type === 'session_info')]
    .flatMap(r => Array.isArray(r.missing) ? r.missing.filter((v: unknown) => typeof v === 'string') : []))];
  return { ref: reference(header), header, records, original, missing, diagnostics, raw: parsed.records.map((r: any) => r.raw) };
}

export function readAnnotations(input: Uint8Array): AnnotationFile {
  const parsed = readJsonl(input);
  const records: RecordData[] = [], superseded = new Set<string>(), seen = new Set<string>();
  const diagnostics: Diagnostic[] = parsed.diagnostics.map((d: any) => ({ code: d.code, line: d.line }));
  for (const { value: r, line, numbers } of parsed.records) {
    if (r.type !== 'annotation' || typeof r.id !== 'string' || seen.has(r.id)
        || typeof r.session !== 'string' || validateRecord(r, 'annotation', numbers).length
        || (r.supersedes !== undefined && !seen.has(r.supersedes))) {
      diagnostics.push({ code: 'invalid-annotation', line }); continue;
    }
    seen.add(r.id);
    if (r.supersedes !== undefined) superseded.add(r.supersedes);
    records.push(r);
  }
  return { records: latestAnnotations(records.filter(r => !superseded.has(r.id))), diagnostics };
}
function latestAnnotations(records: RecordData[]): RecordData[] {
  const latest = new Map<string, number>();
  for (const r of records) if (['summary', 'outcome', 'title'].includes(r.kind)) {
    const key = JSON.stringify([r.session, r.kind]);
    latest.set(key, Math.max(latest.get(key) ?? -Infinity, Date.parse(r.at)));
  }
  return records.filter(r => !['summary', 'outcome', 'title'].includes(r.kind)
    || Date.parse(r.at) === latest.get(JSON.stringify([r.session, r.kind])));
}

export function loadStore(directory: string, limits = { depth: 16, files: 1000, fileBytes: 64 * 1024 * 1024, totalBytes: 256 * 1024 * 1024 }): { sessions: Session[]; annotations: RecordData[]; diagnostics: Diagnostic[] } {
  const sessions: Session[] = [], annotations: RecordData[] = [], diagnostics: Diagnostic[] = [];
  let files = 0, total = 0;
  function read(file: string): Buffer {
    if (++files > limits.files) throw new Error('Store file limit exceeded.');
    const fd = openSync(file, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
    try {
      const stat = fstatSync(fd);
      if (!stat.isFile() || stat.size > limits.fileBytes) throw new Error('Store file size limit exceeded.');
      const chunks: Buffer[] = [];
      let size = 0;
      for (;;) {
        const chunk = Buffer.alloc(Math.min(64 * 1024, limits.fileBytes - size + 1));
        const count = readSync(fd, chunk, 0, chunk.length, null);
        if (!count) return Buffer.concat(chunks);
        size += count; total += count;
        if (size > limits.fileBytes || total > limits.totalBytes) throw new Error('Store byte limit exceeded.');
        chunks.push(chunk.subarray(0, count));
      }
    } finally { closeSync(fd); }
  }
  function walk(dir: string, depth = 0) {
    if (depth > limits.depth) throw new Error('Store nesting limit exceeded.');
    for (const e of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const file = path.join(dir, e.name);
      if (e.isDirectory()) walk(file, depth + 1);
      else if (e.isFile() && e.name.endsWith('.jsonl')) {
        if (e.name.endsWith('.annotations.jsonl')) {
          const a = readAnnotations(read(file)); annotations.push(...a.records); diagnostics.push(...a.diagnostics);
        } else {
          const bytes = read(file);
          try { sessions.push(readSession(bytes)); }
          catch { diagnostics.push({ code: 'unreadable-session' }); }
        }
      }
    }
  }
  walk(directory);
  const counts = new Map<string, number>();
  for (const s of sessions) counts.set(s.ref, (counts.get(s.ref) ?? 0) + 1);
  for (const s of sessions) if (counts.get(s.ref)! > 1) {
    s.original.clear(); s.diagnostics.push({ code: 'duplicate-session-identity' });
  }
  return { sessions, annotations: latestAnnotations(annotations), diagnostics };
}

export function uniqueCall(s: Session, callId: unknown): RecordData | undefined {
  if (typeof callId !== 'string') return undefined;
  const calls = s.records.filter(r => r.type === 'tool_call' && r.callId === callId);
  return calls.length === 1 ? calls[0] : undefined;
}
export function successful(s: Session, r: RecordData): boolean {
  if (r.status === 'completed') return true;
  if (r.status !== 'unknown' || !uniqueCall(s, r.callId)) return false;
  const results = s.records.filter(x => x.type === 'tool_result' && x.callId === r.callId);
  return results.length === 1 && s.original.has(results[0]) && results[0].status === 'completed';
}
export function sessionSummary(s: Session, available: Set<string>) {
  const unresolved = new Set<string>();
  if (s.header.parent?.session && !available.has(s.header.parent.session)) unresolved.add(s.header.parent.session);
  for (const r of s.records) {
    for (const ref of [r.copiedFrom?.session, r.from, r.subagent?.session]) if (ref && !available.has(ref)) unresolved.add(ref);
    if (r.inferenceId && s.records.filter(x => x.type === 'inference' && x.id === r.inferenceId).length !== 1)
      unresolved.add(`${s.ref}#${component(r.inferenceId)}`);
    if (r.type === 'tool_call' && !s.records.some(x => x.type === 'tool_result' && x.callId === r.callId))
      unresolved.add(citation(s, r));
    if (r.type === 'tool_result' && !uniqueCall(s, r.callId)) unresolved.add(citation(s, r));
    if (r.callId !== undefined && ['file_change', 'vcs', 'approval'].includes(r.type) && !uniqueCall(s, r.callId))
      unresolved.add(citation(s, r));
  }
  const approvals = s.records.filter(r => r.type === 'approval' && s.original.has(r)).map(r => ({
    ref: citation(s, r), decision: r.decision, ...(r.by === undefined ? {} : { by: r.by }),
    pairing: r.callId === undefined ? 'standalone' : uniqueCall(s, r.callId) ? 'paired' : 'unpaired',
  }));
  return { session: s.ref, missing: s.missing, gaps: s.records.filter(r => r.type === 'gap').map(r => ({ ref: citation(s, r), reason: r.reason })),
    approvals, unresolved: [...unresolved], diagnostics: s.diagnostics };
}
